  for (const dx of [-0.028, 0.028]) B.add('gear', onTorso(K.rbox(0.045, 0.1, 0.03, 0.01), Math.PI - 0.75 + dx / 0.165 * 1, 0.975, 0.022), 'hips', C.pouch);

