    B.add('patch', onTorso(K.quad(0.135, 0.036), F, 1.39, 0.0585), 'chest', 0xffffff);
    B.add('patch', onTorso(K.quad(0.21, 0.056), Bk, 1.385, 0.039), 'chest', 0xffffff);
